package ru.lab10.domain;

import java.util.*;
import java.time.LocalDate;

public class Lecturer extends ResearchEmployee {
    private final List<Course> courses = new ArrayList<>();

    Lecturer(String socialSecurityNumber, String name, String email, String researchArea, Institute institute) {
        super(socialSecurityNumber, name, email, researchArea, institute);
    }

    void teachCourse(Course course) {
        if (!course.getLecturers().contains(this)) throw new IllegalArgumentException("Другой преподаватель курса");
        if (courses.contains(course)) throw new IllegalArgumentException("Курс уже назначен");
        courses.add(course);
    }

    public List<Course> getCourses() {
        return Collections.unmodifiableList(courses);
    }
}
